'use strict';
// Local Auto Farm runs only while this game is open and unpaused.
const autoButton=document.createElement('button');autoButton.id='autoFarmBtn';autoButton.className='auto-farm-button';autoButton.onclick=openAutoPanel;$('playScreen').append(autoButton);
function updateAutoHUD(){autoButton.disabled=screen!=='play'||uiBusy();autoButton.textContent=autoFarmActive()?'AUTO · ON':'AUTO';autoButton.classList.toggle('running',autoFarmActive());autoButton.setAttribute('aria-label',autoFarmActive()?'Auto Farm กำลังทำงาน':'Auto Farm พร้อมใช้งาน');const clock=$('autoFarmClock');if(clock)clock.textContent=autoFarmActive()?'ทำงาน':'พร้อมใช้'}
function openAutoPanel(internal=false){if(uiBusy()&&internal!==true)return;
 const body=document.createElement('div');body.className='auto-panel';const clock=document.createElement('div');clock.className='auto-clock';clock.innerHTML='<small>Auto Farm</small><strong id="autoFarmClock"></strong><small>ไม่จำกัดเวลา</small>';clock.querySelector('strong').textContent=autoFarmActive()?'ทำงาน':'พร้อมใช้';body.append(clock);
 const right=document.createElement('div');right.className='auto-options';const slots=document.createElement('div');slots.className='auto-slots';for(let i=0;i<4;i++){const button=document.createElement('button'),id=player.autoFarm.skills[i];button.setAttribute('aria-label','ตั้งสกิล Auto ช่อง '+(i+1));button.innerHTML='<small>'+(i+1)+'</small><span></span>';button.querySelector('span').textContent=id===AUTO_NORMAL?'โจมตีธรรมดา':id?WEAPON_SKILLS[id].name:'เลือกสกิล';button.disabled=autoFarmActive();button.onclick=()=>openAutoPicker(i);slots.append(button)}right.append(slots);
 const note=document.createElement('p');note.textContent='วนใช้ 1 → 2 → 3 → 4 · ข้ามช่องที่ใช้ไม่ได้ · ไม่กดบัฟ · ต้องเปิดเกมไว้';right.append(note);
 const actions=document.createElement('div');actions.className='auto-actions';const help=document.createElement('button');help.textContent='คำอธิบาย';help.onclick=()=>modal('การ Auto Farm','เลือกโจมตีธรรมดาหรือ Active 4 ช่องโดยไม่ใส่ซ้ำตามลำดับของคุณ หากติด CD หรือ MP ไม่พอจะลองช่องถัดไปทันที ไม่กดบัฟและไม่ใช้ยาเอง ชาร์จจนเต็ม และใช้สกิลกดค้างครั้งละ 3 วินาที\nทำงานเฉพาะด่านที่เริ่ม Auto ไม่เปลี่ยนด่านเอง แพ้หรือออกจากด่านจะหยุด\nต้องเปิดเกมไว้และให้เกมทำงานอยู่ เปิด Status/Skill/Enchant แล้วยังฟาร์มต่อ พักเกม สลับแท็บ หรือดับจอจะหยุดฟาร์ม ปิดเกมแล้วเปิดใหม่จะไม่มีรางวัลย้อนหลัง ต้องกดเริ่ม Auto ใหม่\nใช้ Auto ได้ทันที ไม่ต้องซื้อใบหรือสะสมเวลา',[['กลับ',()=>openAutoPanel(true)]]);
 const toggle=document.createElement('button');toggle.id='autoFarmToggle';toggle.className='primary';toggle.textContent=autoFarmActive()?'หยุด Auto':'เริ่ม Auto';toggle.disabled=!autoFarmActive()&&(!run||run.tutorial||run.finished||!player.autoFarm.skills.some(autoActionEnabled));toggle.onclick=()=>{if(autoFarmActive()){stopAutoFarm();openAutoPanel(true)}else if(startAutoFarm()){closeModal();updateAutoHUD();toast('เริ่ม Auto · เปิดเกมไว้เพื่อฟาร์ม')}};actions.append(help,toggle);right.append(actions);
 body.append(right);
 if(!run){const hint=document.createElement('small');hint.textContent='เลือกสกิลได้ที่นี่ จากนั้นเข้าด่านที่ต้องการแล้วกดเริ่ม Auto';right.append(hint)}
 modal('Auto Farm'+(run&&!run.tutorial?' · '+(run.trial?TRIAL:stageById(run.id)).name:''),body,[]);$('modal').classList.add('auto-modal');
}
function openAutoPicker(index){const body=document.createElement('div');body.className='auto-picker';for(const id of [null,AUTO_NORMAL,...Object.values(WEAPON_SKILLS).filter(d=>d.kind==='active'&&weaponSkillEnabled(d.id)).map(d=>d.id)]){const button=document.createElement('button');button.textContent=id===AUTO_NORMAL?'โจมตีธรรมดา':id?WEAPON_SKILLS[id].name+' · ขั้น '+WEAPON_SKILLS[id].tier:'ว่าง';button.disabled=id!==null&&player.autoFarm.skills.some((other,i)=>i!==index&&other===id);button.onclick=()=>{if(setAutoSkill(index,id))openAutoPanel(true)};body.append(button)}modal('เลือก Active · Auto ช่อง '+(index+1),body,[['กลับ',()=>openAutoPanel(true)]])}
const localAutoPress=press;press=function(code,repeat=false){if(autoFarmActive()&&!paused&&!uiBusy()&&screen==='play'){stopAutoFarm('manualInput');toast('หยุด Auto · กลับมาควบคุมเอง')}return localAutoPress(code,repeat)};
const localAutoAssigned=castAssignedSkill;castAssignedSkill=function(slot){if(autoFarmActive()&&!paused&&!uiBusy())stopAutoFarm('manualInput');return localAutoAssigned(slot)};
$('touchJoystick').addEventListener('pointerdown',()=>{if(autoFarmActive()&&!paused&&!uiBusy())stopAutoFarm('manualInput')},true);
window.addEventListener('pagehide',()=>{stopAutoFarm('closed');save()});
updateAutoHUD();
